WITH matched_keys AS (SELECT merchant, id FROM transactions INTERSECT SELECT merchant, id FROM transactions WHERE txn_type = 'REFUND'), kept_rows AS (SELECT s.* FROM transactions s JOIN matched_keys k ON s.merchant = k.merchant AND s.id = k.id) SELECT CASE WHEN amount >= 3400 THEN 'PREMIUM' ELSE 'STANDARD' END AS amount_tier, MAX(amount) FILTER (WHERE txn_type = 'REFUND') AS refund_max_amount, COUNT(CASE WHEN txn_type = 'FEE' THEN 1 END) AS fee_count, STDDEV_SAMP(amount) AS amount_stddev, ROUND(AVG(amount), 2) AS avg_amount, MAX(txn_time) AS last_txn_time FROM kept_rows GROUP BY 1
